   359→        let pairings: Vec<(PartitionedBy, ScalarValue)> = self
   360→            .partition_by
   361→            .iter()
   362→            .cloned()
   363→            .zip(partition_values.iter().cloned())
   364→            .collect();
   365→        let hive_path = to_hive_partition_dir(&pairings)
   366→            .map_err(|e| creator::Error::CreatePartition { source: e.into() })?;
   367→        let duckdb_path = self.partition_dir.join(&hive_path);
