#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Hash)]
pub enum Engine {
    #[default]
    Arrow,
    DuckDB,
    PartitionedDuckDB,
    TableModePartitionedDuckDB,
    Sqlite,
    Turso,
    PostgreSQL,
    Cayenne,
